                '(?i)[\w.-]{0,50}?(?:yandex)(?:[ \t\w.-]{0,20})[\s\'"]{0,3}(?:=|>|:{1,3}=|\|\||:|=>|\?=|,)[\x60\'"\s=]{0,5}(AQVN[A-Za-z0-9_\-]{35,38})(?:[\x60\'"\s;]|\\\[nr]|\z)',
        },
        {
            'id'       => 'yandex-aws-access-token',
            'keywords' => [
                'yandex',
            ],
            'regex' =>
                '(?i)[\w.-]{0,50}?(?:yandex)(?:[ \t\w.-]{0,20})[\s\'"]{0,3}(?:=|>|:{1,3}=|\|\||:|=>|\?=|,)[\x60\'"\s=]{0,5}(YC[a-zA-Z0-9_\-]{38})(?:[\x60\'"\s;]|\\\[nr]|\z)',
        },
